// INCOME PROJECTION — a BAND, its assumptions written down, and a REFUSAL when the history is thin.
//
// A projection is the point where analysis stops describing and starts being acted on: it is what a
// runway figure divides by, what a payoff schedule promises against, and what decides whether a
// balance transfer is safe. So the failure mode is not inaccuracy — it is a single confident number
// that hides how little it knows.
//
// Three commitments follow, and each is enforced here rather than left to the reader:
//
//  1. A BAND, NEVER A POINT. Low / expected / high, every month. The low is the one a plan is built
//     on; the expected is the one a plan is *hoped* on.
//  2. THE BAND WIDENS WITH DISTANCE. Month six is not as knowable as month one. A flat band asserts
//     that it is, which is the specific lie that makes a twelve-month plan collapse in month four.
//  3. IT REFUSES. Given two months of history it returns `projectable: false` and no numbers — not a
//     band of zeroes, which reads as "you will earn nothing" and is worse than saying nothing.
import { type Money, money, sum } from "@/features/finance/lib/money";
import type { IncomeAnalysis, IncomeSource } from "@/features/finance/lib/income";
import { daysBetween, monthOf } from "@/features/finance/lib/txn";

export interface MonthBand {
  /** `YYYY-MM`. */
  readonly month: string;
  /** What the month looks like if everything that can reasonably go wrong does. Plan on this. */
  readonly low: Money;
  /** The median-driven figure. Hope on this. */
  readonly expected: Money;
  readonly high: Money;
}

/** Why a source the analysis found is not in the projection. */
export type ExclusionReason = "lapsed";

export interface ExcludedSource {
  readonly key: string;
  readonly label: string;
  readonly reason: ExclusionReason;
  readonly lastSeen: string;
  /** What it WOULD have contributed. Named so the size of the exclusion is visible. */
  readonly monthlyEquivalent: Money;
}

export interface ProjectionTotal {
  readonly low: Money;
  readonly expected: Money;
  readonly high: Money;
}

export interface IncomeProjection {
  readonly projectable: boolean;
  /** Present ONLY when `projectable` is false, and it says what was missing. */
  readonly reason?: string;
  /** Empty when not projectable — never a band of zeroes. */
  readonly months: readonly MonthBand[];
  /** Absent when not projectable, so a caller cannot accidentally add zero into a runway. */
  readonly total?: ProjectionTotal;
  /** Every judgement this projection made, in prose, for the reader to disagree with. */
  readonly assumptions: readonly string[];
  readonly excluded: readonly ExcludedSource[];
  readonly sourcesUsed: number;
}

export interface ProjectionOptions {
  /** `YYYY-MM-DD` — what "now" is. Passed IN, never read from a clock, so a re-run gives the same
   *  answer and a test is not a moving target. */
  readonly asOf: string;
  /** How many months forward. */
  readonly months?: number;
  /** Fewest WHOLE months of history before a projection is honest. Below it, this refuses. */
  readonly minMonthsObserved?: number;
  /** A source unseen for this many of its own periods is treated as ended. */
  readonly lapseFactor?: number;
  /** How much the band widens per month out, as a fraction of the observed spread. */
  readonly driftPerMonth?: number;
  /** Widening applied per month EVEN TO A PERFECTLY STEADY SOURCE, as a fraction of expected.
   *  Four months of an identical salary is not evidence that a salary cannot stop; a band that
   *  stayed pinned to the observed spread would say it is. */
  readonly floorUncertainty?: number;
}

/** Nominal days between receipts at each cadence — what "overdue" is measured against. */
const CADENCE_DAYS: Record<string, number> = {
  weekly: 7,
  biweekly: 14,
  semimonthly: 15.2,
  monthly: 30.4,
};

/** `YYYY-MM` arithmetic. Proper modulo, so stepping backwards over a year boundary works. */
export function addMonths(ym: string, n: number): string {
  const total = Number(ym.slice(0, 4)) * 12 + (Number(ym.slice(5, 7)) - 1) + n;
  const mm = ((total % 12) + 12) % 12;
  const yy = (total - mm) / 12;
  return `${String(yy).padStart(4, "0")}-${String(mm + 1).padStart(2, "0")}`;
}

/** A source is ended, not merely late, once it is overdue by several of its own periods. */
function isLapsed(s: IncomeSource, asOf: string, lapseFactor: number): boolean {
  const period = CADENCE_DAYS[s.cadence];
  if (period === undefined) return false;
  return daysBetween(s.lastSeen, asOf) > period * lapseFactor;
}

/** A source's smallest and largest receipt, scaled to a month the same way `typical` was. */
function monthlyRange(s: IncomeSource): { low: number; high: number } {
  if (s.typical.minor === 0) return { low: 0, high: 0 };
  const perMonth = s.monthlyEquivalent.minor / s.typical.minor;
  return { low: Math.round(s.low.minor * perMonth), high: Math.round(s.high.minor * perMonth) };
}

export function projectIncome(
  analysis: IncomeAnalysis,
  currency: string,
  opts: ProjectionOptions,
): IncomeProjection {
  const {
    asOf,
    months = 6,
    minMonthsObserved = 3,
    lapseFactor = 2.5,
    driftPerMonth = 0.15,
    floorUncertainty = 0.02,
  } = opts;

  const excluded: ExcludedSource[] = [];
  const live: IncomeSource[] = [];
  for (const s of analysis.sources) {
    if (isLapsed(s, asOf, lapseFactor)) {
      // A CONTRACT THAT ENDED IS NOT INCOME. Projecting a source last seen four months ago forward
      // for another six is the most expensive mistake this module can make, because it is invisible:
      // the total looks healthy and every downstream figure inherits money that is not coming.
      excluded.push({
        key: s.key,
        label: s.label,
        reason: "lapsed",
        lastSeen: s.lastSeen,
        monthlyEquivalent: s.monthlyEquivalent,
      });
      continue;
    }
    live.push(s);
  }

  const refuse = (reason: string): IncomeProjection => ({
    projectable: false,
    reason,
    months: [],
    assumptions: [],
    excluded,
    sourcesUsed: 0,
  });

  if (analysis.monthsObserved < minMonthsObserved) {
    return refuse(
      `${analysis.monthsObserved} whole month(s) of history; ${minMonthsObserved} are needed before a projection means anything`,
    );
  }
  if (live.length === 0) {
    return refuse(
      excluded.length
        ? `every income source has lapsed — the most recent receipt was ${excluded.map((e) => e.lastSeen).sort().pop()}`
        : "no repeating income source was found",
    );
  }

  const expected = sum(live.map((s) => s.monthlyEquivalent), currency).minor;
  const ranges = live.map(monthlyRange);
  const sourceLow = ranges.reduce((a, r) => a + r.low, 0);
  const sourceHigh = ranges.reduce((a, r) => a + r.high, 0);

  // THE FLOOR HONOURS THE WORST MONTH THAT ACTUALLY HAPPENED. Summing each source's smallest
  // payment assumes every source paid — but a month where one simply did not pay is worse than
  // that sum, and it is the month a plan has to survive. Whichever is lower wins.
  const worst = analysis.worstMonth.minor;
  const clamped = worst < sourceLow;
  const lowBase = clamped ? worst : sourceLow;
  const highBase = Math.max(sourceHigh, expected);

  const bands: MonthBand[] = [];
  const start = monthOf(asOf);
  for (let i = 0; i < months; i++) {
    const widen = 1 + driftPerMonth * i;
    const floor = floorUncertainty * (i + 1) * expected;
    const low = Math.max(0, Math.round(expected - ((expected - lowBase) * widen + floor)));
    const high = Math.round(expected + ((highBase - expected) * widen + floor));
    bands.push({
      // The month `asOf` falls in is already partly spent, so the projection starts at the NEXT one.
      month: addMonths(start, i + 1),
      low: money(low, currency),
      expected: money(expected, currency),
      high: money(high, currency),
    });
  }

  const assumptions = [
    `Projected from ${analysis.monthsObserved} whole month(s) of history across ${live.length} repeating source(s).`,
    "Expected is each source's MEDIAN receipt scaled to a month, so one unusually large payment does not move it.",
    `The band widens ${Math.round(driftPerMonth * 100)}% of the observed spread per month, plus ${Math.round(floorUncertainty * 100)}% of expected — month ${months} is less certain than month 1, and the numbers say so.`,
    `Starts at ${bands[0].month}: the month containing ${asOf} is already partly spent.`,
  ];
  if (clamped) {
    assumptions.push(
      `The floor uses the worst whole month observed rather than the sum of each source's smallest payment — a month where a source did not pay at all is worse than a month where it paid little.`,
    );
  }
  if (analysis.oneOff.length) {
    const total = sum(analysis.oneOff.map((t) => t.amount), currency);
    assumptions.push(
      `${analysis.oneOff.length} one-off receipt(s) totalling ${total.minor} minor units are NOT projected — a refund is not income you can plan on receiving again.`,
    );
  }
  if (excluded.length) {
    assumptions.push(
      `${excluded.length} source(s) excluded as lapsed: ${excluded.map((e) => `${e.label} (last seen ${e.lastSeen})`).join(", ")}.`,
    );
  }

  return {
    projectable: true,
    months: bands,
    total: {
      low: sum(bands.map((b) => b.low), currency),
      expected: sum(bands.map((b) => b.expected), currency),
      high: sum(bands.map((b) => b.high), currency),
    },
    assumptions,
    excluded,
    sourcesUsed: live.length,
  };
}

/** The band for one month of a projection, or undefined if it is outside the horizon. */
export const bandFor = (p: IncomeProjection, month: string): MonthBand | undefined =>
  p.months.find((b) => b.month === month);

/** What the projection says is safe to commit to per month — the LOW of the furthest month, because
 *  a commitment made now has to survive the least certain month it reaches. */
export function committableMonthly(p: IncomeProjection): Money | undefined {
  if (!p.projectable || !p.months.length) return undefined;
  return p.months[p.months.length - 1].low;
}

