import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import { analyseIncome, type IncomeAnalysis, type IncomeSource } from "@/features/finance/lib/income";
import type { Txn } from "@/features/finance/lib/txn";
import {
  addMonths,
  bandFor,
  committableMonthly,
  projectIncome,
} from "@/features/finance/lib/projection";

// SYNTHETIC FIXTURES ONLY. No real statement, balance or account number belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");
const pay = (date: string, description: string, major: number, account = "checking"): Txn => ({
  date,
  description,
  amount: usd(major),
  account,
});

/** Every other Friday, the same amount — the shape a salary actually has. */
function biweekly(from: string, n: number, major: number, description = "ACME PAYROLL DIRECT DEP"): Txn[] {
  const out: Txn[] = [];
  const start = Date.parse(`${from}T00:00:00Z`);
  for (let i = 0; i < n; i++) {
    const d = new Date(start + i * 14 * 86_400_000).toISOString().slice(0, 10);
    out.push(pay(d, description, major));
  }
  return out;
}

/** A hand-built analysis, so a claim about the projection is not also a claim about the analyser. */
function source(over: Partial<IncomeSource> = {}): IncomeSource {
  return {
    key: "acme payroll",
    label: "ACME PAYROLL",
    account: "checking",
    cadence: "monthly",
    typical: usd(4000),
    low: usd(4000),
    high: usd(4000),
    occurrences: 6,
    firstSeen: "2026-01-01",
    lastSeen: "2026-06-01",
    consistency: 1,
    stability: "steady",
    monthlyEquivalent: usd(4000),
    ...over,
  };
}

function analysis(over: Partial<IncomeAnalysis> = {}): IncomeAnalysis {
  return {
    sources: [source()],
    typicalMonth: usd(4000),
    worstMonth: usd(4000),
    bestMonth: usd(4000),
    monthsObserved: 6,
    oneOff: [],
    ...over,
  };
}

describe("addMonths", () => {
  it("crosses a year boundary in both directions", () => {
    expect(addMonths("2026-11", 3)).toBe("2027-02");
    expect(addMonths("2026-02", -3)).toBe("2025-11");
    expect(addMonths("2026-12", 1)).toBe("2027-01");
    expect(addMonths("2026-01", -1)).toBe("2025-12");
  });

  it("is a no-op at zero and round-trips", () => {
    expect(addMonths("2026-07", 0)).toBe("2026-07");
    expect(addMonths(addMonths("2026-03", 25), -25)).toBe("2026-03");
  });
});

describe("projectIncome — the refusal", () => {
  it("REFUSES on thin history and returns NO NUMBERS — not a band of zeroes", () => {
    const p = projectIncome(analysis({ monthsObserved: 2 }), "USD", { asOf: "2026-06-15" });
    expect(p.projectable).toBe(false);
    // A band of zeroes reads as "you will earn nothing", which is a worse lie than silence.
    expect(p.months).toEqual([]);
    expect(p.total).toBeUndefined();
    expect(p.reason).toMatch(/2 whole month/);
    expect(p.reason).toMatch(/3 are needed/);
  });

  it("refuses when every source has lapsed, and says which date it last saw money", () => {
    const p = projectIncome(
      analysis({ sources: [source({ lastSeen: "2026-01-05" })] }),
      "USD",
      { asOf: "2026-06-15" },
    );
    expect(p.projectable).toBe(false);
    expect(p.months).toEqual([]);
    expect(p.reason).toContain("2026-01-05");
    expect(p.excluded).toHaveLength(1);
  });

  it("projects once the history clears the bar", () => {
    const p = projectIncome(analysis({ monthsObserved: 3 }), "USD", { asOf: "2026-06-15" });
    expect(p.projectable).toBe(true);
    expect(p.reason).toBeUndefined();
    expect(p.months).toHaveLength(6);
  });
});

describe("projectIncome — a lapsed source is dropped, not carried", () => {
  it("excludes a source unseen for several of its own periods and NAMES it", () => {
    const p = projectIncome(
      analysis({
        sources: [
          source({ key: "acme payroll", label: "ACME PAYROLL", lastSeen: "2026-06-01" }),
          source({ key: "old gig", label: "OLD GIG LLC", lastSeen: "2026-02-10", monthlyEquivalent: usd(1500) }),
        ],
        monthsObserved: 6,
      }),
      "USD",
      { asOf: "2026-06-15" },
    );
    expect(p.projectable).toBe(true);
    expect(p.sourcesUsed).toBe(1);
    expect(p.excluded.map((e) => e.label)).toEqual(["OLD GIG LLC"]);
    expect(p.excluded[0].reason).toBe("lapsed");
    // THE MONEY IS GONE FROM THE TOTAL. This is the whole point: a contract that ended must not
    // keep paying in the forecast, where it is invisible and every downstream figure inherits it.
    expect(p.months[0].expected.minor).toBe(usd(4000).minor);
    expect(p.assumptions.join(" ")).toContain("OLD GIG LLC");
    expect(p.assumptions.join(" ")).toContain("2026-02-10");
  });

  it("keeps a source that is merely a little late", () => {
    // Monthly, last paid 40 days ago: overdue, but 40 < 30.4 * 2.5. Late is not ended.
    const p = projectIncome(
      analysis({ sources: [source({ lastSeen: "2026-05-06" })] }),
      "USD",
      { asOf: "2026-06-15" },
    );
    expect(p.excluded).toEqual([]);
    expect(p.sourcesUsed).toBe(1);
  });
});

describe("projectIncome — the band widens with distance", () => {
  it("month 6 is wider than month 1 for a variable source", () => {
    const p = projectIncome(
      analysis({
        sources: [source({ low: usd(3000), high: usd(5000), consistency: 0.7, stability: "variable" })],
        worstMonth: usd(3000),
      }),
      "USD",
      { asOf: "2026-06-15", months: 6 },
    );
    const first = p.months[0];
    const last = p.months[5];
    expect(last.low.minor).toBeLessThan(first.low.minor);
    expect(last.high.minor).toBeGreaterThan(first.high.minor);
    // Monotone, not merely different at the ends.
    for (let i = 1; i < p.months.length; i++) {
      expect(p.months[i].low.minor).toBeLessThanOrEqual(p.months[i - 1].low.minor);
      expect(p.months[i].high.minor).toBeGreaterThanOrEqual(p.months[i - 1].high.minor);
    }
  });

  it("STILL widens for a source that has never varied once", () => {
    // Four months of an identical salary is not evidence that a salary cannot stop. A band pinned to
    // the observed spread would be flat here and would assert exactly that.
    const p = projectIncome(analysis(), "USD", { asOf: "2026-06-15", months: 6 });
    expect(p.months[0].low.minor).toBeLessThan(p.months[0].expected.minor);
    expect(p.months[5].low.minor).toBeLessThan(p.months[0].low.minor);
    expect(p.months[5].high.minor).toBeGreaterThan(p.months[0].high.minor);
  });

  it("never projects a negative month", () => {
    const p = projectIncome(
      analysis({ sources: [source({ low: usd(0), high: usd(9000) })], worstMonth: usd(0) }),
      "USD",
      { asOf: "2026-06-15", months: 24 },
    );
    for (const b of p.months) expect(b.low.minor).toBeGreaterThanOrEqual(0);
  });

  it("expected is flat across the horizon — only the uncertainty moves", () => {
    const p = projectIncome(analysis(), "USD", { asOf: "2026-06-15", months: 4 });
    expect(new Set(p.months.map((b) => b.expected.minor)).size).toBe(1);
  });
});

describe("projectIncome — the floor honours the worst month that actually happened", () => {
  it("uses the worst observed month when it is below the sum of each source's smallest payment", () => {
    // Every payment was $4,000, so summing the smallest gives $4,000 — but one month the source did
    // not pay at all. That month is what a plan has to survive, and the floor must know it.
    const withSkip = projectIncome(
      analysis({ worstMonth: usd(0) }),
      "USD",
      { asOf: "2026-06-15", months: 1, driftPerMonth: 0, floorUncertainty: 0 },
    );
    expect(withSkip.months[0].low.minor).toBe(0);
    expect(withSkip.assumptions.join(" ")).toContain("worst whole month observed");

    const noSkip = projectIncome(
      analysis({ worstMonth: usd(4000) }),
      "USD",
      { asOf: "2026-06-15", months: 1, driftPerMonth: 0, floorUncertainty: 0 },
    );
    expect(noSkip.months[0].low.minor).toBe(usd(4000).minor);
    expect(noSkip.assumptions.join(" ")).not.toContain("worst whole month observed");
  });
});

describe("projectIncome — the horizon", () => {
  it("starts the month AFTER asOf, because this month is already partly spent", () => {
    const p = projectIncome(analysis(), "USD", { asOf: "2026-06-15", months: 3 });
    expect(p.months.map((b) => b.month)).toEqual(["2026-07", "2026-08", "2026-09"]);
    expect(bandFor(p, "2026-08")).toBe(p.months[1]);
    expect(bandFor(p, "2026-06")).toBeUndefined();
  });

  it("crosses the year end", () => {
    const late = analysis({ sources: [source({ lastSeen: "2026-11-01" })] });
    const p = projectIncome(late, "USD", { asOf: "2026-11-20", months: 3 });
    expect(p.months.map((b) => b.month)).toEqual(["2026-12", "2027-01", "2027-02"]);
  });

  it("totals what it actually banded, and nothing else", () => {
    const p = projectIncome(analysis(), "USD", { asOf: "2026-06-15", months: 4 });
    const add = (xs: number[]) => xs.reduce((a, b) => a + b, 0);
    expect(p.total!.low.minor).toBe(add(p.months.map((b) => b.low.minor)));
    expect(p.total!.expected.minor).toBe(add(p.months.map((b) => b.expected.minor)));
    expect(p.total!.high.minor).toBe(add(p.months.map((b) => b.high.minor)));
  });

  it("commits only to the least certain month it reaches", () => {
    const p = projectIncome(analysis(), "USD", { asOf: "2026-06-15", months: 6 });
    expect(committableMonthly(p)).toEqual(p.months[5].low);
    expect(committableMonthly(projectIncome(analysis({ monthsObserved: 1 }), "USD", { asOf: "2026-06-15" })))
      .toBeUndefined();
  });
});

describe("projectIncome — over a real analysis", () => {
  const txns = biweekly("2026-01-05", 11, 2000);

  it("projects a biweekly salary end to end", () => {
    const a = analyseIncome(txns, "USD");
    expect(a.sources).toHaveLength(1);
    expect(a.sources[0].cadence).toBe("biweekly");

    const p = projectIncome(a, "USD", { asOf: "2026-05-25", months: 6 });
    expect(p.projectable).toBe(true);
    // Biweekly is 26 payments a year, so a month is 2.1667 of them — never 2.
    expect(p.months[0].expected.minor).toBe(Math.round(usd(2000).minor * (26 / 12)));
  });

  it("names one-off money as excluded from the projection rather than folding it in", () => {
    const a = analyseIncome([...txns, pay("2026-03-11", "IRS TREAS 310 TAX REF", 3200)], "USD");
    const p = projectIncome(a, "USD", { asOf: "2026-05-25" });
    expect(a.oneOff).toHaveLength(1);
    expect(p.assumptions.join(" ")).toContain("one-off receipt");
    // A tax refund is not income you can plan on receiving again.
    expect(p.months[0].expected.minor).toBe(Math.round(usd(2000).minor * (26 / 12)));
  });
});
